<script>
 import { onMount } from 'svelte';
 let tamil=$state(false), name=$state(''), feedback=$state(''), color=$state('yellow'), striking=$state(false), saved=$state(false), destroying=$state(false), destroyed=$state(false), error=$state('');
 const timers=[];
 const t=(en,ta)=>tamil?ta:en;
 const count=(s)=>Array.from(s).length;
 function later(fn,ms){timers.push(setTimeout(fn,ms));}
 function language(){tamil=!tamil;try{localStorage.setItem('shyam-language',tamil?'ta':'en');}catch{}document.documentElement.lang=tamil?'ta':'en';}
 function edited(){error='';}
 function submit(event){
  event.preventDefault();if(saved)return;
  if(count(name.trim())<2||count(name.trim())>50||count(feedback.trim())<5||count(feedback.trim())>300){error=t('Use 2–50 characters for your name and 5–300 for your note.','பெயர் 2–50 எழுத்துகள்; கருத்து 5–300 எழுத்துகள் இருக்க வேண்டும்.');return;}
  // Local theatrical demo: no network requests, identifiers, or message storage.
  saved=true;error='';
  later(()=>{striking=true;},1300);
  later(()=>{destroying=true;},1900);
  later(()=>{destroyed=true;name='';feedback='';},4900);
 }
 onMount(()=>{try{tamil=localStorage.getItem('shyam-language')==='ta';}catch{}return()=>timers.forEach(clearTimeout);});
 function reset(){timers.forEach(clearTimeout);timers.length=0;saved=false;striking=false;destroying=false;destroyed=false;name='';feedback='';error='';}
</script>
<svelte:head><title>Leave a note · Shyam J</title><meta name="description" content="A little sticky note for Shyam. Share your thoughts about the portfolio."/></svelte:head>
<div class="board" class:striking class:destroying class:destroyed inert={destroyed}>
 <header><a href="/">← {t('back to my world','முகப்புக்குத் திரும்ப')}</a><span>SJ / {t('NOTEBOARD','கருத்துப் பலகை')}</span><button onclick={language}>{t('தமிழ்','English')}</button></header>
 <main>
  <div class="intro"><p class="overline">{t('A LITTLE NOTE GOES A LONG WAY','ஒரு சிறிய கருத்து, பெரிய உதவி')}</p><h1>{t('Leave a little','ஒரு சிறிய')}<br/><em>{t('thought.','கருத்து.')}</em></h1><p>{t('Loved something? Spotted something? Pin a note for me.','பிடித்ததா? ஏதாவது கவனித்தீர்களா? எனக்காக ஒரு கருத்தை எழுதுங்கள்.')}</p><div class="power-scene">
 <img src="/media/feedback-power.png" alt={t('Thanos raising the glowing Infinity Gauntlet','ஒளிரும் கையுறையை உயர்த்தும் தானோஸ்')} width="2048" height="1152"/>
 <span class="gauntlet-glow" aria-hidden="true"></span>

 </div></div>
  <section class="note" class:mint={color==='mint'} class:pink={color==='pink'} class:saved>
   <div class="impact" aria-hidden="true"><span></span><span></span><span></span>{#each Array.from({length:12},(_,i)=>i) as i}<i style={'--angle:'+(i*30)+'deg'}></i>{/each}</div><div class="tape" aria-hidden="true"></div><span class="pin" aria-hidden="true"></span>
   {#if saved}
    <div class="success" role="status"><span class="check">✓</span><p class="overline">{t('NOTE PINNED','கருத்து ஒட்டப்பட்டது')}</p><h2>{t('Thank you,','நன்றி,')} {name}!</h2><p>{t('Wait… what is Thanos doing?','ஒரு நிமிடம்… தானோஸ் என்ன செய்கிறார்?')}</p><small>{t('Just a playful demo. Nothing was sent or saved.','இது ஒரு விளையாட்டு. எதுவும் அனுப்பப்படவோ சேமிக்கப்படவோ இல்லை.')}</small></div>
   {:else}
    <form onsubmit={submit}>
     <p class="to">{t('To: Shyam','பெறுநர்: ஷ்யாம்')} <span>♡</span></p>
     <label for="note-name">{t('Your name','உங்கள் பெயர்')}</label><input id="note-name" bind:value={name} oninput={edited} disabled={saved} autocomplete="name" placeholder={t('What should I call you?','உங்களை எப்படி அழைப்பது?')} required aria-describedby="note-rules"/>
     <label for="note-message">{t('Your little thought','உங்கள் சிறிய கருத்து')}</label><textarea id="note-message" bind:value={feedback} oninput={edited} disabled={saved} rows="5" placeholder={t('I think your website…','உங்கள் இணையதளம்…')} required aria-describedby="note-rules note-count"></textarea>
     <div class="note-bottom"><div class="swatches" aria-label={t('Note color','குறிப்பின் நிறம்')}>{#each ['yellow','mint','pink'] as c}<button type="button" class={c} aria-label={c} aria-pressed={color===c} onclick={()=>color=c}></button>{/each}</div><span id="note-count" class:over={count(feedback)>300}>{count(feedback)} / 300</span></div>
     <p class="availability">{t('Just for fun — your note stays on this page only.','வேடிக்கைக்காக மட்டும் — உங்கள் கருத்து இந்தப் பக்கத்தில் மட்டுமே இருக்கும்.')}</p>
     <button class="send" type="submit">{t('pin my note ↗','கருத்தை ஒட்டு ↗')}</button>
     {#if error}<p class="error" role="alert">{error}</p>{/if}
    </form>
   {/if}
  </section>
  <svg class="power-bolt" viewBox="0 0 1000 700" preserveAspectRatio="none" aria-hidden="true"><path d="M310 420 L370 390 L405 430 L470 365 L505 405 L575 335 L630 370 L715 300"/><path d="M470 365 L480 435 L535 455"/></svg>
 <aside><span aria-hidden="true">✦</span><p>{t('Honest thoughts. Kind words.','நேர்மையான கருத்துகள். கனிவான வார்த்தைகள்.')}</p><small id="note-rules">{t('Name: 2–50 characters. Note: 5–300. This is a demo; nothing is collected.','பெயர்: 2–50 எழுத்துகள். கருத்து: 5–300. இது ஒரு விளையாட்டு; எதுவும் சேகரிக்கப்படாது.')}</small></aside>
 </main>
 <footer>{t('a small corner for your big ideas.','உங்கள் பெரிய யோசனைகளுக்கு ஒரு சிறிய இடம்.')} <span>SHYAM J © {new Date().getFullYear()}</span></footer>
</div>
{#if destroying}<div class="dust-cloud" aria-hidden="true">{#each Array.from({length:90},(_,i)=>i) as i}<i style={'--x:'+((i*37)%100)+'%;--y:'+((i*53)%100)+'%;--dx:'+(((i*71)%500)-250)+'px;--dy:'+(((i*29)%500)-150)+'px;--delay:'+((i%8)*.06)+'s;--spin:'+(i*43)+'deg;--size:'+(4+i%13)+'px'}></i>{/each}</div>{/if}
{#if destroyed}<div class="aftermath"><div class="aftermath-inner"><img src="/media/feedback-power.png" alt="Thanos"/><p class="overline">{t('PERFECTLY BALANCED.','சரியான சமநிலை.')}</p><h1>{t('Note pinned.','கருத்து ஒட்டப்பட்டது.')}<br/><em>{t('Page destroyed.','பக்கம் அழிக்கப்பட்டது.')}</em></h1><p>{t('Thanos took your note a little too seriously.','தானோஸ் உங்கள் கருத்தை கொஞ்சம் தீவிரமாக எடுத்துக்கொண்டார்.')}</p><div class="end-actions"><button onclick={reset}>{t('restore the page ↺','பக்கத்தை மீட்க ↺')}</button><a href="/">{t('back to my world ↗','முகப்புக்குத் திரும்ப ↗')}</a></div></div></div>{/if}
<style>
 .board{overflow:hidden;transition:background 2s}.destroying{background:#171020!important}.destroying header,.destroying .intro>p,.destroying .intro h1,.destroying aside,.destroying footer{animation:disappear 2.6s forwards;pointer-events:none}.destroying .note{animation:annihilate 2.6s forwards!important;pointer-events:none}.destroying .power-scene{transform:scale(1.08);transition:transform 1s}.destroyed{visibility:hidden}.dust-cloud{position:fixed;inset:0;pointer-events:none;z-index:30;overflow:hidden}.dust-cloud i{position:absolute;left:var(--x);top:var(--y);width:var(--size);height:var(--size);background:#ead898;box-shadow:0 0 10px #ab7cea66;animation:dust 3s var(--delay) both}.dust-cloud i:nth-child(3n){background:#a58dc9}.aftermath{position:fixed;inset:0;background:radial-gradient(ellipse at 50% 30%,#2c193d,#0e0b13 70%);color:#f7f0df;z-index:40;overflow:auto;display:grid;place-items:center;padding:35px;text-align:center;animation:reveal-end .6s both}.aftermath-inner{max-width:650px}.aftermath img{width:min(480px,70vw);height:240px;object-fit:cover;mask-image:radial-gradient(ellipse,#000 30%,transparent 72%)}.aftermath h1{font:500 clamp(32px,4vw,54px)/1.15 Georgia,serif;margin:18px 0}.aftermath h1 em{color:#c19af2}.aftermath p{line-height:1.6}.aftermath small{color:#b8abc7}.end-actions{display:flex;justify-content:center;gap:16px;flex-wrap:wrap;margin-top:28px}.end-actions button,.end-actions a{padding:13px 20px;border:1px solid #b88cdb66;background:#3d2855;border-radius:30px;color:#fff;text-decoration:none;font:14px Arial;cursor:pointer}.end-actions a{background:transparent}@keyframes annihilate{0%{transform:rotate(2deg);opacity:1;filter:none}18%{transform:translateX(12px) rotate(5deg);filter:brightness(1.8)}35%{transform:translateX(-8px) rotate(-3deg)}70%{transform:translate(40px,90px) rotate(12deg);filter:blur(3px);opacity:.45;clip-path:polygon(0 12%,20% 5%,30% 40%,55% 20%,80% 60%,100% 45%,100% 100%,0 100%)}100%{transform:translate(90px,170px) rotate(20deg);opacity:0;filter:blur(15px);clip-path:polygon(0 80%,20% 75%,30% 95%,55% 80%,80% 95%,100% 85%,100% 100%,0 100%)}}@keyframes disappear{30%{opacity:1}100%{opacity:0;filter:blur(10px);transform:translate(25px,80px) rotate(5deg)}}@keyframes dust{0%{opacity:0;transform:scale(.2)}15%{opacity:1}100%{opacity:0;transform:translate(var(--dx),var(--dy)) rotate(var(--spin)) scale(.1)}}@keyframes reveal-end{from{opacity:0}to{opacity:1}}@media(prefers-reduced-motion:reduce){.destroying .note,.destroying header,.destroying .intro>p,.destroying .intro h1,.destroying aside,.destroying footer{animation:none!important;opacity:0}.dust-cloud{display:none}.aftermath{animation:none}}

 .power-scene{position:relative;height:245px;width:100%;margin-top:20px;isolation:isolate}.power-scene img{width:100%;height:100%;object-fit:cover;object-position:45% center;mask-image:radial-gradient(ellipse at 50% 51%,#000 40%,transparent 74%);filter:saturate(1.1);animation:power-breathe 6s ease-in-out infinite}.gauntlet-glow{position:absolute;left:64%;top:35%;width:30px;height:30px;border-radius:50%;background:#c7bcff;box-shadow:0 0 24px 10px #8a70edaa;opacity:.7;pointer-events:none}.power-bolt{position:absolute;inset:0;width:100%;height:100%;z-index:4;pointer-events:none;opacity:0;overflow:visible}.power-bolt path{fill:none;stroke:#ece2ff;stroke-width:5;filter:drop-shadow(0 0 5px #904dff) drop-shadow(0 0 15px #a478ff)}.impact{position:absolute;left:20%;top:22%;width:100px;height:100px;pointer-events:none;z-index:5}.impact>span{position:absolute;inset:0;border:3px solid #b38af4;border-radius:50%;opacity:0}.impact i{position:absolute;left:50%;top:50%;width:5px;height:6px;border-radius:50%;background:#fff4ce;opacity:0;box-shadow:0 0 8px #8d58d7}.striking .gauntlet-glow{animation:charge 1.6s both}.striking .power-bolt{animation:bolt 1.6s both}.striking .note{animation:note-hit 1.6s both}.striking .impact>span{animation:shock 1.6s both}.striking .impact>span:nth-child(2){animation-delay:.12s}.striking .impact>span:nth-child(3){animation-delay:.24s}.striking .impact i{animation:spark 1.6s both}@keyframes power-breathe{50%{transform:translateY(-5px) scale(1.025)}}@keyframes charge{0%,100%{transform:scale(1);opacity:.6}30%{transform:scale(2.5);opacity:1}45%{transform:scale(4);opacity:1}70%{transform:scale(.8)}}@keyframes bolt{0%,32%,57%,100%{opacity:0}35%,43%,53%{opacity:1}39%,48%{opacity:.25}}@keyframes note-hit{0%,33%,100%{transform:rotate(2deg)}36%{transform:translate(14px,4px) rotate(5deg)}41%{transform:translate(-9px,-2px) rotate(-2deg)}48%{transform:translate(5px,1px) rotate(3deg)}65%{transform:rotate(2deg)}}@keyframes shock{0%,33%{opacity:0;transform:scale(.1)}36%{opacity:1;transform:scale(.2)}80%,100%{opacity:0;transform:scale(4)}}@keyframes spark{0%,33%{opacity:0;transform:rotate(var(--angle)) translateX(0)}37%{opacity:1}90%,100%{opacity:0;transform:rotate(var(--angle)) translateX(180px)}}@media(prefers-reduced-motion:reduce){.power-scene img{animation:none}.striking .power-bolt,.striking .note,.striking .impact>span,.striking .impact i,.striking .gauntlet-glow{animation:none}}

 :global(body){margin:0}.board{min-height:100vh;background:#eee9de;color:#353b32;font-family:Arial,sans-serif;background-image:radial-gradient(#9d998329 .9px,transparent .9px);background-size:18px 18px;padding:30px 6vw;box-sizing:border-box}.board header{display:flex;align-items:center;justify-content:space-between;gap:20px;font-size:12px;font-weight:700;letter-spacing:.04em}.board a{color:inherit;text-decoration:none}.board button{font:inherit;cursor:pointer}.board header button{border:1px solid #353b3255;border-radius:30px;background:transparent;padding:10px 18px}.board main{position:relative;isolation:isolate;max-width:1100px;margin:70px auto 45px;display:grid;grid-template-columns:1fr 1.15fr;gap:25px 70px;align-items:center}.overline{font-size:11px;letter-spacing:.15em;font-weight:700}.intro h1{font-size:clamp(50px,6.4vw,90px);line-height:1.03;font-weight:500;letter-spacing:-.065em;margin:24px 0}.intro h1 em{font-family:Georgia,serif;font-weight:400;color:#708465}.intro>p:not(.overline){max-width:300px;line-height:1.8;color:#62695d}.note{position:relative;padding:38px 38px 30px;background:#fff0aa;box-shadow:3px 22px 35px #52483626,0 2px 3px #52483610;transform:rotate(2deg);transition:background .4s,transform .4s;animation:arrive .8s both}.note:hover,.note:focus-within{transform:rotate(0)}.note.mint{background:#d5ebcc}.note.pink{background:#f7d3da}.tape{position:absolute;width:140px;height:35px;background:#fdfaf6aa;top:-17px;left:calc(50% - 70px);transform:rotate(-5deg);box-shadow:0 1px 2px #0001}.pin{position:absolute;top:19px;right:22px;width:10px;height:10px;background:#c86d55;border-radius:50%;box-shadow:1px 3px 4px #0003}.to{font-family:Georgia,serif;font-style:italic;font-size:25px;display:flex;justify-content:space-between;margin:0 0 28px}.to span{color:#aa7357}.note label{display:block;font-size:12px;font-weight:bold;margin:22px 0 6px}.note input,.note textarea{display:block;box-sizing:border-box;width:100%;border:0;border-radius:0;border-bottom:1px solid #72662c44;background:transparent;color:#343a32;font-family:Georgia,serif;font-size:18px;padding:9px 0;outline-offset:5px}.note textarea{resize:vertical;line-height:32px;background:repeating-linear-gradient(transparent 0,transparent 31px,#72662c25 31px,#72662c25 32px);min-height:160px;max-height:340px}.note input::placeholder,.note textarea::placeholder{color:#6b694d99}.note-bottom{display:flex;justify-content:space-between;align-items:center;margin:16px 0;font-size:11px;color:#686747}.swatches{display:flex;gap:8px}.swatches button{width:20px;height:20px;border-radius:50%;border:1px solid #353b3244}.swatches button[aria-pressed=true]{outline:1px solid #353b32;outline-offset:3px}.yellow{background:#fff0aa}.mint{background:#d5ebcc}.pink{background:#f7d3da}.send,.send:hover{transform:translateY(-2px)}button:disabled{opacity:.6;cursor:wait}.availability{font-size:12px;line-height:1.5;color:#6b694d}.over,.error{color:#9c322d}.error{font-size:13px;line-height:1.5}.board aside{grid-column:2;text-align:center;transform:rotate(-2deg);font-size:14px;color:#697660}.board aside>span{font-size:30px}.board aside p{margin:7px}.board aside small{display:block;font-size:11px;line-height:1.6;max-width:370px;margin:0 auto}.board footer{display:flex;justify-content:space-between;gap:20px;font-size:11px;color:#7b8074;padding:20px 0}.board footer span{font-size:10px;letter-spacing:.1em}.success{min-height:400px;display:flex;flex-direction:column;justify-content:center;text-align:center}.success h2{font:italic 36px Georgia,serif;overflow-wrap:anywhere}.success>p:not(.overline){line-height:1.6}.check{font-size:55px;color:#557f40;animation:stamp .5s}.saved{transform:rotate(-2deg)}@keyframes arrive{from{opacity:0;transform:translateY(35px) rotate(7deg)}to{opacity:1;transform:translateY(0) rotate(2deg)}}@keyframes stamp{from{transform:scale(2);opacity:0}to{transform:scale(1);opacity:1}}@media(max-width:900px){.board main{gap:25px;}.note{padding:32px 25px}}@media(max-width:650px){.board main{grid-template-columns:1fr;margin-top:35px}.board aside{grid-column:1}.board header>span{display:none}.board footer{flex-wrap:wrap}.intro h1{font-size:58px}}@media(prefers-reduced-motion:reduce){.note,.check{animation:none;transition:none}}
</style>
